@DataJpaTest
class OrderRepositoryTest {

    @Autowired
    private OrderRepository orderRepository;

    @Autowired
    private TestEntityManager entityManager;

    @Test
    void findByCustomerNameReturnsMatchingOrders() {
        entityManager.persist(new Order(null, "Amy"));
        entityManager.persist(new Order(null, "Ben"));

        List<Order> results = orderRepository.findByCustomerName("Amy");

        assertThat(results).hasSize(1);
        assertThat(results.get(0).getCustomerName()).isEqualTo("Amy");
    }

    @Test
    void databaseIsEmptyAtTheStartOfEachTest() {
        // Even though the previous test persisted two orders, this test
        // starts from zero -- @DataJpaTest rolled that transaction back.
        assertThat(orderRepository.findAll()).isEmpty();
    }
}

@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class OrderApiIntegrationTest {

    @Autowired
    private TestRestTemplate restTemplate;

    @Test
    void creatingAndFetchingAnOrderWorksEndToEnd() {
        CreateOrderRequest request = new CreateOrderRequest("Amy", List.of("mug"));

        ResponseEntity<Order> createResponse =
                restTemplate.postForEntity("/api/orders", request, Order.class);
        assertThat(createResponse.getStatusCode()).isEqualTo(HttpStatus.OK);

        Long id = createResponse.getBody().getId();
        ResponseEntity<Order> getResponse =
                restTemplate.getForEntity("/api/orders/" + id, Order.class);
        assertThat(getResponse.getBody().getCustomerName()).isEqualTo("Amy");
    }
}

