@WebMvcTest(OrderController.class)
class OrderControllerPostTest {

    @Autowired
    private MockMvc mockMvc;
    @Autowired
    private ObjectMapper objectMapper;
    @MockBean
    private OrderService orderService;

    @Test
    void creatingOrderWithBlankCustomerNameReturns400WithFieldError() throws Exception {
        CreateOrderRequest request = new CreateOrderRequest("", List.of("mug"));

        mockMvc.perform(post("/api/orders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(request)))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.errors.customerName").value("Customer name is required"));

        verifyNoInteractions(orderService);
    }
}

@Test
void creatingOrderPassesCorrectDataToService() throws Exception {
    CreateOrderRequest request = new CreateOrderRequest("Amy", List.of("mug"));
    given(orderService.create(any())).willReturn(new Order(1L, "Amy", List.of("mug")));

    mockMvc.perform(post("/api/orders")
                    .contentType(MediaType.APPLICATION_JSON)
                    .content(objectMapper.writeValueAsString(request)))
            .andExpect(status().isOk());

    verify(orderService).create(argThat(req ->
            req.getCustomerName().equals("Amy") && req.getItems().equals(List.of("mug"))
    ));
}

