@Test
void deletingOrderCallsServiceExactlyOnceWithCorrectId() throws Exception {
    mockMvc.perform(delete("/api/orders/42"))
            .andExpect(status().isNoContent());

    verify(orderService, times(1)).deleteById(42L);
    verify(orderService, never()).deleteById(argThat(id -> id != 42L));
}

@Test
void getOrderForWrongIdCausesConfusingNullPointerException() throws Exception {
    // Stubbed for id=1, but the controller (due to a real bug) actually calls findById(0)
    given(orderService.findById(1L)).willReturn(new Order(1L, "Amy", List.of("mug")));

    // GET /api/orders/1 -- but suppose the controller mistakenly does findById(id - 1)
    mockMvc.perform(get("/api/orders/1"))
            .andExpect(status().isOk());   // fails: 500, not 200

    // orderService.findById(0L) was never stubbed, so it silently returned null,
    // and the controller's own call to order.getCustomerName() threw NullPointerException
    // -- the real bug is the controller's off-by-one, but the mock's silence made the
    // failure surface as an NPE deep in serialization rather than a clear assertion mismatch.

